const $ = s => document.querySelector(s);
const canvas=$('#scene'),ctx=canvas.getContext('2d');
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
let w=innerWidth,h=innerHeight,dpr=1,spread=0,targetSpread=0,rotation=0,targetRotation=0,zoom=1,demo=false,lastTime=0,elapsed=0;
let pointer=null,dragged=false,photoHitboxes=[],photoCursor=0;
let seed=24; const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
const colors=['#f6d88e','#ffe9b0','#c3994a','#fff2d2','#dca659','#c34950','#89a79b'];
const sprites=colors.map(color=>{const c=document.createElement('canvas');c.width=c.height=48;const x=c.getContext('2d'),g=x.createRadialGradient(24,24,0,24,24,24);g.addColorStop(0,'#fff7df');g.addColorStop(.1,color);g.addColorStop(.28,color+'bb');g.addColorStop(1,color+'00');x.fillStyle=g;x.fillRect(0,0,48,48);return c});
const points=Array.from({length:w<600?1800:2700},(_,i)=>{const t=rand(),y=t*3.8-1.85,a=rand()*Math.PI*2,r=(1-t)*1.38*(i%3===0?.92:Math.sqrt(rand()));const az=rand()*Math.PI*2,sy=rand()*2-1,sr=1.2+Math.pow(rand(),.4)*2.9;return{x:Math.cos(a)*r,y,z:Math.sin(a)*r,sx:Math.cos(az)*Math.sqrt(1-sy*sy)*sr,sy:sy*sr*.78,sz:Math.sin(az)*Math.sqrt(1-sy*sy)*sr,size:.6+rand()*1.8,color:i%17===0?5:i%29===0?6:Math.floor(rand()*5),phase:rand()*Math.PI*2}});
// Spiral garland follows the cone rather than a flat triangle.
for(let i=0;i<450;i++){const t=i/450,a=t*Math.PI*19,r=(1-t)*1.4;points.push({x:Math.cos(a)*r,y:t*3.8-1.85,z:Math.sin(a)*r,sx:Math.cos(a)*3.5,sy:(t-.5)*5,sz:Math.sin(a)*3.5,size:1.25,color:1,phase:rand()*6.28})}
const snow=Array.from({length:135},()=>({x:rand(),y:rand(),r:.35+rand()*1.15,speed:.01+rand()*.028,phase:rand()*6.28}));
function postcard(i){const c=document.createElement('canvas');c.width=400;c.height=470;const x=c.getContext('2d');const palettes=[['#152933','#588184'],['#27213d','#aa7890'],['#413324','#ac8d61'],['#182d36','#5978a6']];const [dark,light]=palettes[i%4];const g=x.createLinearGradient(0,0,0,420);g.addColorStop(0,dark);g.addColorStop(1,light);x.fillStyle=g;x.fillRect(0,0,400,470);x.fillStyle='#fff1cf';x.beginPath();x.arc(285,92,29,0,7);x.fill();for(let k=0;k<55;k++){x.globalAlpha=.2+rand()*.7;x.beginPath();x.arc(rand()*400,rand()*330,rand()*1.7+.5,0,7);x.fill()}x.globalAlpha=1;for(let n=0;n<3;n++){x.fillStyle=['#cad4d2','#e4e6d9','#f7edda'][n];x.beginPath();x.moveTo(0,320+n*25);for(let k=0;k<=400;k+=20)x.lineTo(k,300+n*30+Math.sin(k*.012+n*2)*30);x.lineTo(400,470);x.lineTo(0,470);x.fill()}for(let n=0;n<5;n++){const px=35+n*73,py=335+Math.sin(n*2+i)*17,sz=25+rand()*30;x.fillStyle='#1c3839';x.beginPath();x.moveTo(px,py-sz);x.lineTo(px-sz*.42,py+12);x.lineTo(px+sz*.42,py+12);x.fill();x.fillRect(px-2,py,4,20)}x.fillStyle='#f8edcd';x.font='italic 24px Georgia';x.textAlign='center';x.fillText(['A winter wish','Silent night','Little moments','Stay golden'][i%4],200,440);const image=new Image();image.src=c.toDataURL();return image}
let photos=Array.from({length:8},(_,i)=>({image:postcard(i),phase:i*.785,y:(i%4)*.87-1.35}));
function project(x,y,z){const cs=Math.cos(rotation),sn=Math.sin(rotation),rx=x*cs+z*sn,rz=z*cs-x*sn,scale=Math.min(w*.29,h*.112)*zoom,depth=6/(6-rz*.32);return{x:w/2+rx*scale*depth,y:h*.53-y*scale*depth,z:rz,scale:scale*depth}}
function star(x,y,r,alpha=1){ctx.save();ctx.translate(x,y);ctx.globalAlpha=alpha;ctx.shadowColor='#f7d176';ctx.shadowBlur=25;ctx.fillStyle='#ffe4a0';ctx.beginPath();for(let i=0;i<10;i++){const a=i*Math.PI/5-Math.PI/2,rr=i%2?r*.43:r;ctx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}ctx.closePath();ctx.fill();ctx.restore()}
function render(now){const dt=Math.min((now-lastTime)/1000||.016,.05);lastTime=now;elapsed+=dt;if(demo){const next=(Math.floor(elapsed/6)%2);if(next!==targetSpread)setSpread(next,false)}spread+=(targetSpread-spread)*(1-Math.exp(-dt*3.5));if(!reduce&&!pointer)targetRotation+=dt*(.13+spread*.06);rotation+=(targetRotation-rotation)*(1-Math.exp(-dt*6));ctx.clearRect(0,0,w,h);
const glow=ctx.createRadialGradient(w/2,h*.57,0,w/2,h*.57,Math.min(w*.65,h*.65));glow.addColorStop(0,'#59432119');glow.addColorStop(.55,'#26223110');glow.addColorStop(1,'#07090e00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
for(const s of snow){if(!reduce)s.y=(s.y+dt*s.speed)%1;ctx.globalAlpha=.15+.28*(.5+.5*Math.sin(elapsed+s.phase));ctx.fillStyle='#d8dfeb';ctx.beginPath();ctx.arc(s.x*w+Math.sin(elapsed*.2+s.phase)*15,s.y*h,s.r,0,7);ctx.fill()}ctx.globalAlpha=1;
const floor=ctx.createRadialGradient(w/2,h*.81,0,w/2,h*.81,Math.min(w*.27,200));floor.addColorStop(0,'#c3953520');floor.addColorStop(1,'#b5872700');ctx.save();ctx.translate(0,h*.81*.8);ctx.scale(1,.2);ctx.fillStyle=floor;ctx.fillRect(0,0,w,h);ctx.restore();
const items=points.map(p=>{const k=spread,swirl=Math.sin(elapsed*.55+p.phase)*.04*k;return{p,q:project(p.x*(1-k)+p.sx*k+swirl,p.y*(1-k)+p.sy*k,p.z*(1-k)+p.sz*k)}});
items.sort((a,b)=>a.q.z-b.q.z);ctx.globalCompositeOperation='lighter';for(const {p,q} of items){const tw=reduce?.8:.65+.35*Math.sin(elapsed*1.8+p.phase);ctx.globalAlpha=(.48+q.z*.07)*tw;const r=p.size*(q.scale/90)*3.2;ctx.drawImage(sprites[p.color],q.x-r,q.y-r,r*2,r*2)}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
photoHitboxes=[];const cards=photos.map((p,i)=>{const r=spread*2.35+.55;return{p,i,q:project(Math.cos(p.phase)*r,p.y*(1+spread*.35),Math.sin(p.phase)*r)}}).sort((a,b)=>a.q.z-b.q.z);
for(const {p,i,q} of cards){if(!p.image.complete)continue;const size=(.15+spread*.35)*q.scale,ph=size*1.13;ctx.save();ctx.translate(q.x,q.y);ctx.rotate(Math.sin(p.phase)*.1);ctx.globalAlpha=.55+spread*.45;ctx.shadowColor='#e6bb62';ctx.shadowBlur=spread*13+3;ctx.fillStyle='#b18b4a';ctx.fillRect(-size/2-3,-ph/2-3,size+6,ph+6);ctx.shadowBlur=0;ctx.fillStyle='#faf0da';ctx.fillRect(-size/2-1,-ph/2-1,size+2,ph+2);const im=p.image,iw=im.naturalWidth,ih=im.naturalHeight,ratio=Math.max(size/iw,ph/ih),cw=size/ratio,ch=ph/ratio;ctx.drawImage(im,(iw-cw)/2,(ih-ch)/2,cw,ch,-size/2,-ph/2,size,ph);ctx.restore();if(spread>.45)photoHitboxes.push({x:q.x-size/2,y:q.y-ph/2,w:size,h:ph,i})}
const top=project(0,2.04+spread*.15,0);star(top.x,top.y,Math.max(9,top.scale*.14),1-spread*.5);if(!reduce)star(top.x,top.y,Math.max(11,top.scale*.2),.08+.07*Math.sin(elapsed*2));
requestAnimationFrame(render)}requestAnimationFrame(render);
function setSpread(value,manual=true){targetSpread=clamp(value,0,1);$('#state-label').textContent=targetSpread>.5?'每一颗星，都是一个心愿':'星光正在聚拢';$('#scatter').textContent=targetSpread>.5?'✧ 聚拢成树':'✧ 散开星光';if(manual&&demo){demo=false;$('#demo').setAttribute('aria-pressed','false')}}
$('#scatter').onclick=()=>setSpread(targetSpread>.5?0:1);
$('#demo').onclick=()=>{demo=!demo;$('#demo').setAttribute('aria-pressed',String(demo));if(demo){elapsed=6;setSpread(1,false)}toast(demo?'自动演示已开启，每 6 秒切换一次':'自动演示已关闭')};
function openPhoto(i){photoCursor=i+1;$('#large-photo').src=photos[i].image.src;if(!$('#photo-dialog').open)$('#photo-dialog').showModal()}
$('#close-photo').onclick=()=>$('#photo-dialog').close();$('#photo-dialog').onclick=e=>{if(e.target===$('#photo-dialog'))$('#photo-dialog').close()};
canvas.onpointerdown=e=>{pointer={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};dragged=false;canvas.setPointerCapture(e.pointerId)};
canvas.onpointermove=e=>{if(!pointer||e.pointerId!==pointer.id)return;const dx=e.clientX-pointer.x;targetRotation+=dx*.008;pointer.x=e.clientX;pointer.y=e.clientY;if(Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>7)dragged=true};
canvas.onpointerup=e=>{if(!pointer||e.pointerId!==pointer.id)return;pointer=null;if(dragged)return;const card=[...photoHitboxes].reverse().find(p=>e.clientX>=p.x&&e.clientX<=p.x+p.w&&e.clientY>=p.y&&e.clientY<=p.y+p.h);if(card)openPhoto(card.i);else setSpread(targetSpread>.5?0:1)};canvas.onpointercancel=()=>pointer=null;
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom-e.deltaY*.001,.65,1.55)},{passive:false});
addEventListener('keydown',e=>{if(e.code==='Space'&&!$('#photo-dialog').open&&!['BUTTON','INPUT'].includes(document.activeElement.tagName)){e.preventDefault();setSpread(targetSpread>.5?0:1)}});
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('当前浏览器未开放全屏，可使用浏览器全屏按钮')}};
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
$('#photos').onclick=()=>$('#photo-input').click();
$('#photo-input').onchange=async e=>{const files=[...e.target.files].slice(0,16);if(!files.length)return;const images=[];for(const file of files){if(!file.type.startsWith('image/'))continue;if(file.size>25*1024*1024){toast('已跳过超过 25 MB 的照片');continue}try{const bitmap=await createImageBitmap(file),c=document.createElement('canvas'),ratio=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));c.width=Math.max(1,Math.round(bitmap.width*ratio));c.height=Math.max(1,Math.round(bitmap.height*ratio));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();const im=new Image();im.src=c.toDataURL('image/jpeg',.88);await im.decode();images.push(im)}catch{toast('有照片未能读取，请选择 JPG、PNG 或 WebP 图片')}}if(images.length){photos=images.map((image,i)=>({image,phase:i/images.length*Math.PI*2,y:(i%4)*.87-1.35}));setSpread(1);toast(`已放入 ${images.length} 张照片，仅保留在本次页面中`)}e.target.value=''};
let detector=null,stream=null,cameraBusy=false,cameraGeneration=0,inferenceTimer=null,lastVideoTime=-1,lastGesture='',gestureFrames=0,pinchWasDown=false,lastPinch=0;
function stopCamera(){cameraGeneration++;if(inferenceTimer)clearTimeout(inferenceTimer);inferenceTimer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;$('#camera').srcObject=null;$('.camera-panel').hidden=true;$('#camera-toggle').innerHTML='<span>◎</span> 开启手势';$('#camera-toggle').disabled=false;cameraBusy=false;lastGesture='';gestureFrames=0;pinchWasDown=false;$('#hint').textContent='也可以点击画面切换，拖动旋转，滚轮缩放'}
$('#camera-toggle').onclick=async()=>{if(stream||cameraBusy){stopCamera();return}if(!navigator.mediaDevices?.getUserMedia){toast('请通过 localhost 或 HTTPS 打开页面，再使用摄像头');return}const generation=++cameraGeneration;cameraBusy=true;$('#camera-toggle').disabled=true;$('#camera-toggle').textContent='正在加载手势…';try{const media=await navigator.mediaDevices.getUserMedia({video:{width:640,height:480,facingMode:'user'},audio:false});if(generation!==cameraGeneration){media.getTracks().forEach(t=>t.stop());return}stream=media;$('#camera').srcObject=media;await $('#camera').play();$('.camera-panel').hidden=false;if(!detector){const {HandLandmarker,FilesetResolver}=await import('./vendor/vision_bundle.mjs');const vision=await FilesetResolver.forVisionTasks('./vendor/wasm');const options={baseOptions:{modelAssetPath:'./vendor/hand_landmarker.task',delegate:'GPU'},runningMode:'VIDEO',numHands:1,minHandDetectionConfidence:.5,minTrackingConfidence:.5};try{detector=await HandLandmarker.createFromOptions(vision,options)}catch{options.baseOptions.delegate='CPU';detector=await HandLandmarker.createFromOptions(vision,options)}}if(generation!==cameraGeneration)return;cameraBusy=false;$('#camera-toggle').disabled=false;$('#camera-toggle').textContent='◎ 关闭手势';$('#hint').textContent='将一只手完整放入镜头：张开散开，握拳聚拢，捏合查看照片';lastVideoTime=-1;detectHands(generation)}catch(error){if(generation!==cameraGeneration)return;stopCamera();const messages={NotAllowedError:'摄像头权限未开启，可在浏览器地址栏中允许后重试',NotFoundError:'未找到摄像头，仍可使用鼠标和触屏操作',NotReadableError:'摄像头正在被其他应用占用，请关闭占用后重试'};toast(messages[error.name]||'手势模型加载失败，请刷新页面重试；鼠标和触屏仍可使用');console.error('Hand control:',error)}};
function detectHands(generation){if(!stream||generation!==cameraGeneration)return;try{const video=$('#camera');if(video.readyState>=2&&video.currentTime!==lastVideoTime){lastVideoTime=video.currentTime;const result=detector.detectForVideo(video,performance.now()),lm=result.landmarks?.[0];if(lm){const dist=(a,b)=>Math.hypot(lm[a].x-lm[b].x,lm[a].y-lm[b].y),palm=dist(0,9),pinch=dist(4,8)/Math.max(palm,.02),open=[8,12,16,20].filter(i=>dist(i,0)>dist(i-2,0)*1.17).length;const gesture=pinch<.26?'pinch':open>=3?'open':open<=1?'fist':'move';if(gesture===lastGesture)gestureFrames++;else{lastGesture=gesture;gestureFrames=1}if(gestureFrames>=3){if(gesture==='open'){setSpread(1);$('#camera-state').textContent='✧ 张开 · 星光散开'}else if(gesture==='fist'){setSpread(0);$('#camera-state').textContent='✦ 握拳 · 聚拢成树'}else if(gesture==='pinch'){if(!pinchWasDown&&performance.now()-lastPinch>1800&&!$('#photo-dialog').open){openPhoto(photoCursor%photos.length);lastPinch=performance.now()}$('#camera-state').textContent='▧ 捏合 · 珍藏瞬间'}else $('#camera-state').textContent='手掌已识别';pinchWasDown=gesture==='pinch'}if(!$('#photo-dialog').open)targetRotation+=(.5-lm[9].x)*.07}else{$('#camera-state').textContent='请将手掌放入镜头';lastGesture='';gestureFrames=0;pinchWasDown=false}}inferenceTimer=setTimeout(()=>detectHands(generation),85)}catch(error){console.error('Hand tracking:',error);stopCamera();toast('手势识别中断，可重新开启；鼠标和触屏仍可使用')}}
